<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';require __DIR__.'/../src/Inventory/InventoryAccounting.php';
use Kulturhus\Verein\{Database,Finance,Inventory,InventoryAccounting};
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','Synthetic A'),('b','Synthetic B');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('a','a','member',1),('b','b','member',1),('reader','a','member',0)");$key=fn()=>bin2hex(random_bytes(16));$n=0;function check($ok,$label){global $n;if(!$ok)throw new RuntimeException($label);$n++;echo "PASS $label\n";}
$f=new Finance($db,'a');$iv=new Inventory($db,'a');$entry=$f->createEntry(['kind'=>'expense','description'=>'Synthetic acquisition','counterparty'=>'Fictional supplier','document_date'=>'2026-09-07','due_date'=>'2026-09-07','category'=>'inventory','positions'=>[['description'=>'Equipment','amount'=>'100','tax_rate'=>'0','sphere'=>'1','account'=>'06300'],['description'=>'Office material','amount'=>'20','tax_rate'=>'0','sphere'=>'1','account'=>'68150']]],$key());$item=$iv->saveItem('',0,['name'=>'Synthetic item','source_kind'=>'expense','source_id'=>$entry],$key());
$rows=InventoryAccounting::forItem($db,'a',$item);check(count($rows)===1&&count($rows[0]['positions'])===2&&!$rows[0]['specific'],'whole invoice distinctly labeled');check($rows[0]['positions'][0]['account_code']==='06300','original leading-zero account preserved');
$db->prepare('INSERT INTO invoice_position_items VALUES(?,?,?,?,?,?,?,?)')->execute(['a',$entry,1,$item,1,'Equipment','a',gmdate('c')]);$rows=InventoryAccounting::forItem($db,'a',$item);check($rows[0]['specific']&&count($rows[0]['positions'])===1,'specific item link only shows its original position');
check(InventoryAccounting::forItem($db,'reader',$item)===[],'inventory-only actor sees no financial details');try{InventoryAccounting::forItem($db,'b',$item);throw new RuntimeException('foreign item leaked');}catch(DomainException){check(true,'foreign club rejected');}
check(count($f->entries())===1&&$f->entry($entry)['amount_cents']===12000,'readback creates no accounting duplicate');echo "$n inventory accounting checks passed\n";
